242	    /**
243	     * Maximum number of owners allowed in a single city. Creating an owner in a city that has
244	     * already reached this many owners is rejected as a conflict.
245	     */
246	    static final int MAX_OWNERS_PER_CITY = 50;
247	
248	    /**
249	     * Maximum number of owners allowed to register on a single day. Creating an owner once a day has
250	     * already reached this many registrations is rejected as a rate-limit violation.
251	     */
252	    static final int MAX_OWNERS_PER_DAY = 100;
253	
254	    /**
255	     * Number of owners that must already have registered on a day before a new registration is
256	     * flagged with a bulk-signup warning. Once the count already recorded for the day exceeds this
257	     * value, the new owner carries {@code bulkSignupWarning == true}.
258	     */
259	    static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
260	
261	    @Override
262	    @Transactional
263	    public String createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
264	        rejectIdentityCollision(owner);
265	        List<Owner> householdMembers = findHouseholdMembers(owner);
266	        long ownersInCity = ownerRepository.countByCity(owner.getCity());
267	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
268	            throw new CityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
269	        }
270	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
271	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
272	        long ownersOnDate = ownerRepository.countByRegistrationDate(owner.getRegistrationDate());
273	        if (ownersOnDate >= MAX_OWNERS_PER_DAY) {
274	            throw new DailyOwnerLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
275	        }
276	        owner.setBulkSignupWarning(ownersOnDate > BULK_SIGNUP_WARNING_THRESHOLD);
277	        owner.setNamesakeCount(countNamesakes(owner));
278	        owner.setHouseholdSize(householdMembers.size() + 1);
279	        owner.setCustomerCode(CustomerCodeGenerator.format(
280	            owner.getCity(), owner.getLastName(), ownersInCity + 1));
281	        if (sharesHousehold && !householdMembers.isEmpty()) {
282	            owner.setHouseholdId(joinHousehold(owner, householdMembers));
283	        }
284	        ownerRepository.save(owner);
285	        ownerAuditLogger.ownerCreated(owner);
286	        return owner.getHouseholdId();
287	    }
288	
289	    /**
290	     * Reject creating an owner whose whole {@link OwnerIdentityKey identity key} already belongs to
291	     * another owner. Because the telephone is part of the key, only an existing owner sharing every
292	     * key component (normalized telephone, email and household identifier) is a duplicate.
293	     */
294	    private void rejectIdentityCollision(Owner owner) {
295	        String identityKey = OwnerIdentityKey.of(owner);
296	        boolean collides = ownerRepository.findByTelephone(owner.getTelephone()).stream()
297	            .anyMatch(existing -> identityKey.equals(OwnerIdentityKey.of(existing)));
298	        if (collides) {
299	            throw new DuplicateOwnerException(identityKey);
300	        }
301	    }
302	
303	    /**
304	     * Assign the stable household identifier to the new owner and to every existing member of the
305	     * household, persisting the members whose identifier changes, and return the shared identifier.
306	     */
307	    private String joinHousehold(Owner owner, List<Owner> householdMembers) {
308	        String householdId = HouseholdIdGenerator.generate(owner.getLastName(), owner.getAddress());
309	        for (Owner member : householdMembers) {
310	            if (!householdId.equals(member.getHouseholdId())) {
311	                member.setHouseholdId(householdId);
312	                ownerRepository.save(member);
313	            }
314	        }
315	        return householdId;
316	    }
317	
318	    @Override
